'use strict';
// Two views of the same authorized task records; neither view changes execution or results.
const tmBase={tasksPage,handleAction,tcInfo,render};
const tmView={mode:'records',group:'active',pages:{records:1,monitor:1}};
function tmTime(value){if(value===null||value===undefined||value==='')return null;const n=new Date(value).getTime();return Number.isFinite(n)?n:null;}
function tmUpdated(t){return tmTime(t.lastProgressAt);}
function tmStale(t){const at=tmUpdated(t);return tcBusy(t)&&t.status!=='queued'&&at!==null&&Date.now()-at>10*60*1000;}
function tmProblem(t){return t.status!=='stopped'&&(['failed','partial'].includes(t.status)||!!t.summaryFailed||tmStale(t));}
function tmGroup(t,g=tmView.group){return g==='all'||g==='active'&&tcBusy(t)||g==='queued'&&t.status==='queued'||g==='running'&&tcBusy(t)&&t.status!=='queued'||g==='attention'&&tmProblem(t);}
function tmDuration(ms){if(!Number.isFinite(ms)||ms<0)return '—';const m=Math.floor(ms/60000);return m<1?'不足1分钟':m<60?m+'分钟':Math.floor(m/60)+'小时'+(m%60?m%60+'分钟':'');}
function tmElapsed(t){const queued=t.status==='queued',start=tmTime(queued?t.created:t.startedAt),end=tcBusy(t)?Date.now():tmTime(t.completed||t.finishedAt);return {label:queued?'已等待':tcBusy(t)?'已执行':'执行用时',text:start===null||end===null?'—':tmDuration(end-start)};}
function tmQueue(t){if(t.status!=='queued')return '';const pos=t.queuePosition,wait=t.estimatedWaitSeconds,valid=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0;return '<small>'+(valid(pos)&&Number.isInteger(pos)?'前方 '+pos+' 项任务':'等待调度')+'</small>'+(valid(wait)?'<small>预计等待 '+tmDuration(wait*1000)+'</small>':'');}
function tmFeedback(t){const error=t.error||t.errorMessage||t.failureMessage,updated=tmUpdated(t);return (error?'<span class="tm-error">'+E(error)+'</span>':tmStale(t)?'<span class="tm-caution">超过10分钟未更新进度</span><small>请刷新确认，不代表任务已失败</small>':t.status==='queued'?'等待分配执行资源':t.status==='awaiting'?'等待填写计费基数':t.status==='stopped'?'任务已终止':tmProblem(t)?'请查看运行详情中的失败资料与原因':tcBusy(t)?'执行中':'执行已结束')+'<small>'+(updated===null?'更新时间：—':'最近更新 '+tcDate(t.lastProgressAt))+'</small>';}
function tmFileCounts(t){if(tcMerge(t))return '<span>'+((t.sourceTaskIds||[]).length)+' 项来源任务</span>';const c=tcCount(t);return '<div class="tm-file-counts"><span>成功 <strong>'+c.ok+'</strong></span><span class="'+(c.fail?'tm-error':'')+'">失败 <strong>'+c.fail+'</strong></span><span>'+(t.status==='stopped'?'未处理':'尚未完成')+' <strong>'+c.pending+'</strong></span></div><small>共 '+c.total+' 份资料</small>';}
function tmRow(t){const root=document.createElement('tbody');root.innerHTML=tcRow(t);const row=root.firstElementChild,tds=[...row.children],elapsed=tmElapsed(t);tds[0].remove();tds[2].querySelector('small')?.remove();if(!tcBusy(t))tds[3].querySelectorAll('small').forEach(n=>n.remove());tds[4].innerHTML=tmFileCounts(t);tds[5].innerHTML='<span>'+elapsed.label+' '+elapsed.text+'</span><small>提交 '+tcDate(t.created)+'</small>'+tmQueue(t);tds[6].before(Object.assign(document.createElement('td'),{innerHTML:tmFeedback(t)}));row.querySelectorAll('[data-action=tc-open]').forEach(n=>{n.dataset.action='tm-info';if(n.classList.contains('link'))n.textContent='运行详情';});row.querySelector('[data-action=tc-notes]')?.remove();if(t.status==='queued')tds[3].innerHTML=tag(...tcLabel(t))+'<div class="tc-phase">等待开始</div>';return row.outerHTML;}
function tmTabs(){return '<nav class="tm-mode-tabs" aria-label="任务中心视图">'+[['records','分析结果'],['monitor','运行监控']].map(([key,label])=>'<button type="button" data-action="tm-mode" data-mode="'+key+'" aria-pressed="'+(tmView.mode===key)+'" class="'+(tmView.mode===key?'active':'')+'">'+label+'</button>').join('')+'</nav>';}
tasksPage=function(){const requestedPage=state.taskPage||1,root=document.createElement('div');root.innerHTML=tmBase.tasksPage();const header=root.querySelector('.tc-header');header.querySelector(':scope>div>span')?.remove();header.querySelector('h1')?.after(Object.assign(document.createElement('div'),{className:'tm-navigation',innerHTML:tmTabs()}));
 if(tmView.mode==='records')return root.innerHTML;
 root.querySelector('.tc-page').classList.add('tm-monitor');
 const all=tcAll(),rows=all.filter(t=>tmGroup(t));state.taskPage=Math.max(1,Math.min(requestedPage,Math.ceil(rows.length/tcView.size)||1));
 root.querySelector('[data-action=merge-export]')?.remove();root.querySelector('.tc-selection')?.remove();
 const tabs=root.querySelector('.tc-tabs');tabs.setAttribute('aria-label','运行任务分类');tabs.innerHTML=[['active','进行中'],['queued','排队中'],['running','执行中'],['attention','需关注'],['all','全部']].map(([key,label])=>'<button role="tab" aria-selected="'+(tmView.group===key)+'" class="'+(tmView.group===key?'active':'')+'" data-action="tm-group" data-group="'+key+'">'+label+'<strong>'+all.filter(t=>tmGroup(t,key)).length+'</strong></button>').join('');
 const table=root.querySelector('.tc-table');table.innerHTML='<colgroup><col class="tm-name-col"><col class="tc-tool-col"><col class="tc-status-col"><col class="tm-files-col"><col class="tm-time-col"><col class="tm-feedback-col"><col class="tc-action-col"></colgroup><thead><tr><th>任务名称</th><th>使用工具</th><th>运行状态与阶段</th><th>资料处理情况</th><th>等待 / 执行用时</th><th>最近进展与异常</th><th>操作</th></tr></thead><tbody>'+pageItems(rows,state.taskPage,tcView.size).map(tmRow).join('')+'</tbody>';
 root.querySelector('.tc-empty')?.remove();if(!rows.length)table.insertAdjacentHTML('afterend','<div class="tc-empty">'+I('tasks')+'<h2>当前没有'+(tmView.group==='active'?'进行中的':tmView.group==='attention'?'需关注的':'符合条件的')+'任务</h2><p>可切换分类，或到“分析结果”查看已有结果。</p>'+B('查看分析结果','tm-mode','sm','data-mode="records"')+'</div>');
 const pagination=root.querySelector('.tc-pagination');pagination.querySelector(':scope>span strong').textContent=rows.length;pagination.querySelector(':scope>div>span').textContent=state.taskPage+' / '+Math.max(1,Math.ceil(rows.length/tcView.size));pagination.querySelector('[data-step="-1"]').disabled=state.taskPage<=1;pagination.querySelector('[data-step="1"]').disabled=state.taskPage*tcView.size>=rows.length;
 root.querySelector('.tc-footnote').textContent='运行监控查看执行状态；分析结果与后续业务操作请到“分析结果”。';return root.innerHTML;
};
tcInfo=function(t){const html=tmBase.tcInfo(t);if(!modalData.monitor)return html;const root=document.createElement('div');root.innerHTML=html;root.querySelector('.modalhead h2').textContent='运行详情';root.querySelector('[data-tab=overview]')?.replaceChildren(document.createTextNode('运行概况'));
 if(tcView.infoTab==='overview'){const stage=root.querySelector('.tc-info-stage');stage.innerHTML='<h3>当前阶段</h3>'+tag(...tcLabel(t))+tcProgress(t);const outcome=root.querySelector('.tc-info-outcome'),elapsed=tmElapsed(t);outcome.innerHTML='<h3>资料处理情况</h3>'+tmFileCounts(t)+'<div class="tm-runtime-meta"><p>'+elapsed.label+'：'+elapsed.text+'</p>'+tmQueue(t)+'<p>'+tmFeedback(t)+'</p></div>';}
 const jump=root.querySelector('[data-action=tc-result]');if(jump){if(tcBusy(t))jump.remove();else if(['completed','partial'].includes(t.status))jump.textContent=t.summaryFailed?'查看基础信息':'去工具查看结果';}
 if(tcBusy(t))root.querySelector('.modalfoot .row')?.insertAdjacentHTML('beforeend',B('终止任务','tc-stop','danger sm','data-id="'+E(t.id)+'"'));
 return root.innerHTML;
};
handleAction=function(action,el){if(action==='tm-mode'){const mode=el.dataset.mode;if(!['records','monitor'].includes(mode))return;tmView.pages[tmView.mode]=state.taskPage||1;tmView.mode=mode;state.taskPage=tmView.pages[mode];tcView.scroll=0;render();return;}if(action==='tm-group'){tmView.group=el.dataset.group;state.taskPage=1;tcView.scroll=0;render();return;}if(action==='tm-info'||action==='tc-open'&&tcBusy(state.tasks.find(t=>t.id===el.dataset.id)||{})){const t=state.tasks.find(t=>t.id===el.dataset.id);if(!t)return;tcView.infoTab='overview';return openModal('tc-info',{id:t.id,monitor:true});}if(action==='tc-reset'&&tmView.mode==='monitor')tmView.group='active';return tmBase.handleAction(action,el);};
render=function(){tmBase.render();if(modal==='tc-info'&&modalData.monitor&&tcView.infoTab==='overview'){const body=$('.tc-info-dialog .modalbody'),scroll=body?.scrollTop||0;paintModal();const next=$('.tc-info-dialog .modalbody');if(next)next.scrollTop=scroll;}};
render();
